  str_n11_1_desc = "/",
  str_n11_2_desc = "ขณะพยายามติดตามแหล่งที่มาของสัญญาณประหลาด ทุกคนก็บังเอิญตกลงไปในทางเดินที่ดำมืด จะมีอะไรรออยู่ข้างหน้านะ...?",
  str_n11_3_desc = "สำรวจเมืองกับเชอวาน แต่ก็ต้องระวังตัวให้ดีด้วย...",
  str_n11_4_desc = "/",
  str_n11_5_desc = "เพื่อไขปริศนา คุณพยายามค้นหาแหล่งที่มาของสัญญาณลึกลับ",
  str_n11_6_desc = "ในที่สุดร่างลึกลับก็ปรากฏตัวขึ้น นี่อาจจะเป็นบ้านของพวกเขา? ดูเหมือนว่าแหล่งที่มาของสัญญาณจะอยู่ข้างหลังพวกเขา",
  str_n11_7_desc = "คุณเดินตามบัตเลอร์ไป คุณมีคำถามมากมายเกี่ยวกับวาเลนเซียและเกรเทล",
  str_n11_8_desc = "/",
  str_n11_9_desc = "ระหว่างเดินทางไปยังจุดหมายใหม่ ดูเหมือนเจ้าจะสัมผัสได้ถึงชาวออโรเรียนอีกสองคน...",
  str_n11_10_desc = "ขณะเข้าใกล้พิกัด พบอิคลิพไซท์จำนวนมากรวมตัวกันใกล้กับวาเลนเซียและเกรเทล",
  str_n11_11_desc = "วาเลนเซียไล่เกรเทลออกไป และก่อนที่ใครจะมีเวลาฟื้นตัวจากการต่อสู้ Communicator ของ Rediesel Wrench ก็ดังขึ้น...",
  str_n11_12_desc = "ก่อนที่คุณจะถอดรหัสบันทึกที่พบได้ วาเลนเซียและเกรเทลก็จับพวกคุณไว้...",
  str_n11_13_desc = "/",
  str_n11_14_desc = "Undercity เริ่มล่มสลาย เพื่อประหยัดเวลาจึงตัดสินใจแยกทางกัน",
  str_n11_15_desc = "การโน้มน้าวดูเหมือนจะไม่ได้ผล ท่าทางจะต้องเจอกับการต่อสู้ที่รุนแรงอีกแล้ว",
  str_n11_16_desc = "เวลากำลังจะหมด ถ้าจำเป็นก็ต้องใช้กำลังเพื่อพาตัวสองพี่น้องไป!",
  str_n11_17_desc = "/",
  str_n11_18_desc = "เมืองกำลังล่มสลาย และคุณก็มาถึงพื้นที่อันตราย พร้อมรับความท้าทายที่ยากขึ้นหรือไม่?",
  str_n11_19_desc = "เมืองกำลังล่มสลาย และคุณก็มาถึงพื้นที่อันตราย พร้อมรับความท้าทายที่ยากขึ้นหรือไม่?",
  str_n11_1_desc_long = "โคลอสซัสได้รับสัญญาณประหลาด ขณะที่พวกเขากำลังค้นหาแหล่งที่มา ก็เข้าไปสู่พื้นที่อันน่าทึ่งโดยบังเอิญ",
  str_n11_2_desc_long = "กลายเป็นเมืองแปลก ๆ ที่เต็มไปด้วยผู้พิทักษ์ดรอยด์จำนวนมาก\nSiobhan นักวิชาการจาก Illumina ได้ให้คำแนะนำบางอย่าง—ให้เปลี่ยนเป็นเครื่องแบบพิเศษและกลมกลืนกับฝูงชน",
  str_n11_3_desc_long = "“คุณได้เข้าร่วมโดยสหายของ Siobhan, Florine และ Erica จาก Lumopolis\nในฐานะสมาชิกของแผนกสืบสวนนอกรีตของ Lumopolis พวกเขาดูเหมือนจะอยู่ที่นั่นด้วยจุดประสงค์อื่น\nจึงได้มีการจัดตั้งทีมสำรวจชั่วคราว...\"",
  str_n11_4_desc_long = "มีการแบ่งปันข้อมูลและได้ข้อสรุปว่าเมืองนี้ดูเหมือนจะเป็นเมืองโบราณที่ใช้งานได้ดี\nมันถูกตัดขาดจากโลกภายนอกโดยสิ้นเชิงและได้รับการบำรุงรักษาอย่างมีประสิทธิภาพด้วยเครื่องจักรต่างๆ\nในเวลาเดียวกัน ร่างลึกลับสองร่างกำลังสังเกตจากเงามืด...",
  str_n11_5_desc_long = "\"ในขณะที่พยายามตามหาแหล่งที่มาลึกลับนั้น พื้นดินก็สั่นสะเทือนอีกครั้ง และศัตรูก็เข้ามาประชิดตัวคุณมากขึ้น\nสิ่งที่น่าประหลาดใจยิ่งกว่าคือการปรากฏตัวอย่างกะทันหันของเด็กสาวแปลกหน้าสองคน\nพวกเขาจะเป็นใคร\"",
  str_n11_6_desc_long = "\"พวกเขาอาจจะเป็นลูกสาวของเชมัส นักสำรวจอิลลูมิน่า?\nน่าเสียดายที่ดูเหมือนว่าเชมัสจะเสียชีวิตไปแล้ว\nในขณะที่คุณกำลังจะถามคำถามเพิ่มเติม AI Butler ก็เตือนว่าสถานการณ์นั้นอันตราย และทุกคนควรไปยังที่ปลอดภัยก่อน...\"",
  str_n11_7_desc_long = "\"เมื่อบัตเลอร์พาทุกคนไปยังที่ปลอดภัยในบริเวณโรงงานแล้ว วาเลนเซียก็บรรยายสั้นๆ ว่า \"ชีวิตอัตโนมัติเต็มรูปแบบ\" ที่น่าอิจฉาของพวกเขา\nอย่างไรก็ตาม ท่าทีที่หุนหันพลันแล่นของเอริก้าทำให้เกรเทลเริ่มไม่ไว้ใจ และเธอก็จากไปพร้อมกับวาเลนเซีย\"",
  str_n11_8_desc_long = "\"หลังจากต่อสู้กับการจู่โจมโดยพวก Eclipsites แล้ว Vice ก็ได้รับการถ่ายทอดที่เข้ารหัสอีกครั้งจาก Seamus\nข้อความมีข้อมูลบางอย่างเกี่ยวกับสิ่งที่เกิดขึ้นที่นั่น ตลอดจนพิกัดไปยังจุดหมายปลายทางใหม่\nตอนนี้พวกเขารู้มากขึ้นแล้ว ทุกคนก็เตรียมตัวมุ่งหน้าไปยังตำแหน่งที่เชมัสระบุอย่างรวดเร็ว!\"",
  str_n11_9_desc_long = "\"คุณสองคนช่วยชีวิตชาว Aurorian ชื่อ Ruby และ Rouge ซึ่งเป็นสมาชิก Rediesel Wrench ทั้งคู่\nอย่างไรก็ตาม ทุกคนต่างตกตะลึงกับสิ่งที่พวกเขาพูด: พวกเขาไม่ได้อยู่เหนือพื้นดินแต่อยู่ใต้พื้นดิน?! และท้องฟ้าเป็นเพียงภาพลวงตา?\nหลังจากการเปิดเผยนี้ Ruby ได้มอบ Communicator ให้กับคุณและจากไปพร้อมกับ Rouge\"",
  str_n11_10_desc_long = "\"เมื่อใกล้ถึงที่หมาย ก็เห็นสุริยุปราคาจำนวนหนึ่งมารวมตัวกันใกล้กับบาเลนเซียและเกรเทล\nSiobhan และ Florine ไม่ต้องการปล่อยให้สองพี่น้องต้องอยู่อย่างไร้ที่พึ่ง จึงตัดสินใจกลับไปช่วยพวกเขา ในขณะที่คนอื่นๆ ยังคงสำรวจพิกัดต่อไป\nในไม่ช้าพี่สาวทั้งสองก็ถูกขังอยู่ในการต่อสู้อันขมขื่น เมื่อเห็นว่าบัตเลอร์ชะงักงันภายใต้การรุกคืบของสุริยุปราคา เกรเทลก็ปล่อยลำแสงอันทรงพลังของลูมิน่า\"",
  str_n11_11_desc_long = "“หลังจากรับสายจากรูบี้และรูจ ทุกคนกลับมารวมตัวกันอย่างราบรื่นและในที่สุดก็มาถึงพิกัดที่เชมัสทิ้งไว้\nนี่คือห้องของนายและนางเชมัสที่พวกเขาเก็บไฟล์บันทึกที่เข้ารหัสไว้\nนอกจากนี้ คุณยังได้ค้นพบสุนัขหุ่นยนต์ที่น่าสนใจอีกด้วย\"",
  str_n11_12_desc_long = "\"ในขณะที่ทุกคนกำลังค้นหาห้องของเชมัส วาเลนเซียและเกรเทลก็ปรากฏตัวขึ้น\nพี่สาวโกรธสั่งให้หุ่นโจมตีทุกคน น่าแปลกที่แม้แต่ Eclipsites ยังเชื่อฟังคำสั่งของพวกเขา!\nโชคดีที่ตอนนี้เมืองสั่นสะเทือนอีกครั้ง ทำให้เกรเทลไร้ความสามารถ และเปิดโอกาสให้ทุกคนหนีได้\"",
  str_n11_13_desc_long = "หลังจากหลบหนีจากความโกรธแค้นของวาเลนเซียและเกรเทลได้ชั่วคราว เชอวานก็สามารถถอดรหัสบันทึกของซีมัสได้\nในบันทึกบอกว่าพวกเขามาอยู่ที่นี่ได้อย่างไร และเล่าชีวิตประจำวันของพวกเขากับบัตเลอร์\nเบาะแสสุดท้ายก็ปรากฏขึ้น... ทางออกเดียวที่จะออกไปได้คือผ่านแกนพลังงาน ที่อยู่ลึกเข้าไปในเมือง!",
  str_n11_14_desc_long = "\"กลุ่มตัดสินใจแยกทางกัน ฟลอรีนและคนอื่นๆ ไปตามเบาะแสเข้าไปในเมือง ขณะที่ซิบอนเป็นคนพาคุณกลับ\nเธอจะไม่ทิ้งวาเลนเซียและเกรเทลไว้เบื้องหลัง และมุ่งมั่นที่จะพาพวกเขาออกจากเมืองที่พังทลาย\"",
  str_n11_15_desc_long = "“วาเลนเซียไม่เชื่อเรื่องของคุณ ในขณะที่เกรเทลยังคงเป็นศัตรูกับคุณอย่างเปิดเผย\nหลังจากที่กลุ่มต่อต้านการโจมตีของเธอ เธอก็สลบไปอีกครั้ง ทันใดนั้นเมืองก็สั่นสะเทือนอีกครั้ง ... \"",
  str_n11_16_desc_long = "\"ทุกคนพยายามเข้าไปหาเกรเทลขณะที่เธอล้มลง แต่ถูกบาเลนเซียห้ามไว้ ทำให้เกิดการต่อสู้ที่ดุเดือด\nตามคำสั่งของ Siobhan วาเลนเซียอ่านโน้ตที่เชมัสทิ้งไว้ให้เธอ\nเมื่อได้อ่านคำพูดสุดท้ายของบิดาของเธอ ในที่สุด วาเลนเซียก็ใจอ่อนลงและยอมรับความจริง\nอย่างไรก็ตาม ขณะที่ทุกคนปลอบใจวาเลนเซีย เกรเทลและพ่อบ้านก็จากไปอย่างเงียบๆ...\"",
  str_n11_17_desc_long = "\"ทุกคนรีบไปช่วยเกรเทล และวาเลนเซียก็อาสาตามไป\nคุณมาถึงสถานที่เป้าหมายที่อยู่ลึกเข้าไปในเมือง และพบว่าฟลอรีนและคนอื่นๆ ได้เข้าไปข้างในแล้ว\nคุณสงสัยว่าเกรเทลลงไปที่นั่นด้วยเพื่อปกป้องแกนพลังงานที่ล้มเหลว\nไม่มีใครรู้ว่าเรื่องนี้จะจบลงอย่างไร... ติดตามต่อไป\"",
  str_n11_common_Intro = "โบนัสอีเวนต์",
  str_n11_sign_title = "เข้าเกมให้ครบ 8 วันระหว่างช่วงอีเวนต์ เพื่อรับลูมแอมเบอร์และรูปประจำตัวแบบลิมิเต็ด",
  str_n11_shop_npc_name_1 = "เสียงลึกลับ",
  str_n11_shop_npc_word_1 = "“ท่านประธาน คุณอยู่ที่นั่นหรือเปล่า ภารกิจลับยังคงดำเนินต่อไป ดูเหมือนว่าเราจะยังไม่ถูกค้นพบ\nเจ้าจักรกลตัวร้ายนี้...ขอดูหน้าที่แท้จริงหน่อย...แต่ในนี้มันแน่นจริงๆ...\nการใส่เหรียญแปลก ๆ นี้ดูเหมือนจะใช้งานได้ แต่แน่นอนว่าไม่ใช่สิ่งที่ต้องยุ่ง\nสวัสดี คุณกำลังมองหาสินค้าอะไรอยู่? เดี๋ยวก่อน ไม่มีใครอยู่ที่นี่...\nเพียงพูดว่า \"\"ฉันรักเทพเจ้าแห่งแสง\"\" เพื่อรับของขวัญ *ไอ*\"",
  str_n11_rose_1 = "รางวัลโบนัส!",
  str_n11_rose_2 = "ดาร์กช็อกโกแลตแทนใจ",
  str_n11_rose_3 = "ข้อมูลอีเวนต์",
  str_n11_rose_4 = "ระหว่างความรู้สึกดาร์กช็อกโกแลต นักเดินเรือจะได้รับโบนัสกล่องของขวัญช็อกโกแลตเมื่อรับหีบกิจกรรมรายวัน",
  str_n11_rose_5 = "เหลือเวลา: {1} วัน {2} ชม.",
  str_n11_rose_6 = "เวลาที่เหลืออยู่: {1}ชม. {2} ม",
